mapper.sql:
EXISTS (
           SELECT 1 FROM t_mcp_config WHERE (server_id = t_mcp.server_id and creator_id = #{userId,jdbcType=VARCHAR} and project_id = #{projectId,jdbcType=VARCHAR})
       )

LEFT JOIN t_mcp_config c ON (c.creator_id=#{userId,jdbcType=VARCHAR}
and c.server_id=t_mcp.server_id
and c.project_id=#{projectId,jdbcType=VARCHAR})

mapper.delete:
delete
from t_mcp
where server_id = #{serverId,jdbcType=VARCHAR}
  and project_id = #{projectId,jdbcType=VARCHAR}
  and (visibility!='user' or creator_id=#{userId,jdbcType=VARCHAR})

mapper.select:
select

from t_mcp
where project_id = #{projectId,jdbcType=VARCHAR}

    and workspace_id = #{searchCriteria.workspaceId,jdbcType=VARCHAR}


    and type = #{searchCriteria.type,jdbcType=VARCHAR}


    and server_name = #{searchCriteria.name,jdbcType=VARCHAR}


    and creator_id = #{searchCriteria.userId,jdbcType=VARCHAR}


    and server_id = #{searchCriteria.id,jdbcType=VARCHAR}

order by updated_on desc
